 def pos(self): return self.d.site_xpos[self.sid].copy()
 def ori(self): return self.d.site_xmat[self.sid].reshape(3,3).copy()
 def body(self,n): return self.d.xpos[self.m.body(n).id].copy()
 def ik(self,p,R=None,q=None):
  if R is None:R=self.down
  self.k.qpos[:]=self.d.qpos
  q=self.d.qpos[self.qi].copy() if q is None else q.copy()
  jp=np.zeros((3,self.m.nv)); jr=jp.copy()
  for it in range(150):
   self.k.qpos[self.qi]=q; mujoco.mj_fwdPosition(self.m,self.k)
   e=np.r_[np.array(p)-self.k.site_xpos[self.sid],Rot.from_matrix(R@self.k.site_xmat[self.sid].reshape(3,3).T).as_rotvec()]
