   J=np.vstack([jp[:,self.vi],jr[:,self.vi]])
   dq=J.T@np.linalg.solve(J@J.T+np.eye(6)*1e-4,e)
   q=np.clip(q+dq*min(1,.15/(np.max(np.abs(dq))+1e-9)),self.lo,self.hi)
