 def step(self,q=None,grip=None,base=None,torso=0,mode=-1,n=1):
  a=self.s.hold_targets(); a[:7]=self.d.qpos[self.qi] if q is None else q
  if grip is not None:self.grip=grip
  a[7]=self.grip;a[8:11]=[0,0,0] if base is None else base;a[11]=torso;a[12]=mode
  for _ in range(n):self.s.step(a)
 def move(self,p,R=None,n=60,grip=None):
